public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        throw new IllegalArgumentException("Invalid grid input");
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int depositCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                depositCount++;
                markDeposits(grid, i, j, rows, cols);
            }
        }
    }

    return depositCount;
}

private static void markDeposits(char[][] grid, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@') {
        return;
    }

    grid[i][j] = '*'; // Mark as visited

    markDeposits(grid, i + 1, j, rows, cols); // Down
    markDeposits(grid, i - 1, j, rows, cols); // Up
    markDeposits(grid, i, j + 1, rows, cols); // Right
    markDeposits(grid, i, j - 1, rows, cols); // Left
}

