        int y1 = path[1];
        int x2 = path[2];
        int y2 = path[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            throw new IllegalArgumentException("Path coordinates must be within the grid bounds.");
        }
        grid[y1][x1] = true;
        grid[y2][x2] = true;
    }

    boolean[][] visited = new boolean[n][n];
    boolean[] canReachEnd = new boolean[1];
    canReachEnd[0] = false;

    dfs(grid, startX, startY, endX, endY, visited, canReachEnd);

    return canReachEnd[0] ? "can be travelled" : "cannot be travelled";
}

private static void dfs(boolean[][] grid, int x, int y, int endX, int endY, boolean[][] visited, boolean[] canReachEnd) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[y][x] == false || visited[y][x]) {
        return;
    }

    if (x == endX && y == endY) {
        canReachEnd[0] = true;
        return;
    }

    visited[y][x] = true;

    dfs(grid, x + 1, y, endX, endY, visited, canReachEnd);
    dfs(grid, x - 1, y, endX, endY, visited, canReachEnd);
    dfs(grid, x, y + 1, endX, endY, visited, canReachEnd);
    dfs(grid, x, y - 1, endX, endY, visited, canReachEnd);
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    boolean[][] graph = new boolean[n][n];
    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        graph[u][v] = true;
        graph[v][u] = true; // Assuming undirected graph
    }

    boolean[] visited = new boolean[n];
    if (!dfs(graph, start[0], end[0], visited)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

private static boolean dfs(boolean[][] graph, int current, int target, boolean[] visited) {
    if (current == target) {
        return true;
    }

    visited[current] = true;

    for (int i = 0; i < graph.length; i++) {
        if (graph[current][i] && !visited[i]) {
            if (dfs(graph, i, target, visited)) {
                return true;
            }
        }
    }

    visited[current] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Create a graph to represent the maze
    Map<int[], List<int[]>> graph = new HashMap<>();
    for (int[] path : paths) {
        graph.computeIfAbsent(path[0], k -> new ArrayList<>()).add(path[1]);
        graph.computeIfAbsent(path[1], k -> new ArrayList<>()).add(path[0]);
    }

    // BFS to check if end is reachable from start
    Set<int[]> visited = new HashSet<>();
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited.add(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        for (int[] neighbor : graph.getOrDefault(current, new ArrayList<>())) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check for invalid input
    if (start == null || end == null || paths == null || start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Check if start and end are the same
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Create an adjacency list
    List<List<Integer>> graph = new ArrayList<>(n * n);
    for (int i = 0; i < n * n; i++) {
        graph.add(new ArrayList<>());
    }

    // Populate the adjacency list with paths
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        graph.get(from).add(to);
        graph.get(to).add(from);
    }

    // Use BFS to determine if the end can be reached from the start
    Queue<Integer> queue = new ArrayDeque<>();
    boolean[] visited = new boolean[n * n];
    queue.add(indexOf(n, start[0], start[1]));
    visited[indexOf(n, start[0], start[1])] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        for (int neighbor : graph.get(current)) {
            if (neighbor == indexOf(n, end[0], end[1])) {
                return "can be travelled";
            }
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

private static int indexOf(int n, int row, int col) {
    return row * n + col;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
