    }

    boolean[][] visited = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2) {
            throw new IllegalArgumentException("Invalid path");
        }
        if (path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
            throw new IllegalArgumentException("Invalid path coordinates");
        }
    }

    if (!dfs(n, start[0], start[1], end, paths, visited)) {
        return "cannot be travelled";
    }
    return "can be travelled";
}

private static boolean dfs(int n, int x, int y, int[] end, int[][] paths, boolean[][] visited) {
    if (x == end[0] && y == end[1]) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            for (int[] nextPath : paths) {
                if (nextPath[0] == path[2] && nextPath[1] == path[3] && !visited[nextPath[0]][nextPath[1]]) {
                    if (dfs(n, nextPath[0], nextPath[1], end, paths, visited)) {
                        return true;
                    }
                }
            }
        }
    }
    visited[x][y] = false;
    return false;
}

