        remainderCount[remainder]++;
    }
    if (remainderCount[0] % 2 != 0) {
        return false; // Zero remainder count must be even
    }
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false; // Symmetric remainders must match
        }
    }
    return true;
}

