public boolean canArrange(int[] arr, int k) {
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = (num % k + k) % k; // Ensure non-negative remainder
        remainderCount[remainder]++;
    }
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }
    return remainderCount[0] % 2 == 0; // Check for pairs of remaining elements
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> adjList = new HashMap<>();
    for (int[] edge : edges) {
        adjList.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        adjList.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
    }
    return dfs(0, -1, adjList, hasApple) * 2;
}

private int dfs(int node, int parent, Map<Integer, List<Integer>> adjList, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : adjList.get(node)) {
        if (neighbor != parent) {
            time += dfs(neighbor, node, adjList, hasApple);
        }
    }
    if ((time > 0 || hasApple[node]) && node != 0) {
        time += 2;
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
