public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new List[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }
    return dfs(0, -1, graph, hasApple) * 2;
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        int subtreeTime = dfs(neighbor, node, graph, hasApple);
        if (subtreeTime > 0 || hasApple[neighbor]) {
            time += subtreeTime + 2;
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build the adjacency list representation of the tree
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }

    // Helper function to perform DFS and calculate the minimum time
    int[] time = new int[1]; // Using an array to pass time by reference
    dfs(0, -1, tree, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple, int[] time) {
    boolean hasAppleInSubtree = false;
    for (int neighbor : tree.get(node)) {
        if (neighbor == parent) continue; // Skip the parent node to avoid cycles
        if (dfs(neighbor, node, tree, hasApple, time)) {
            hasAppleInSubtree = true;
            time[0] += 2; // Each visit to a child node adds 2 time units (one for going and one for returning)
        }
    }
    return hasAppleInSubtree || hasApple[node];
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

