public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // If the length of the array is 1, it's impossible to split it into two non-empty arrays
    if (n == 1) {
        return false;
    }

    // Iterate over possible sizes of the first part
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (hasSubarrayWithSum(nums, i, sum * i / n)) {
                return true;
            }
        }
    }

    return false;
}

private boolean hasSubarrayWithSum(int[] nums, int length, int target) {
    Set<Integer> sums = new HashSet<>();
    sums.add(0);
    int currentSum = 0;

    for (int num : nums) {
        currentSum += num;
        if (sums.contains(currentSum - target)) {
            return true;
        }
        sums.add(currentSum);
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if ((totalSum * i) % n == 0) {
            Set<Integer> seen = new HashSet<>();
            seen.add(0);
            int target = (totalSum * i) / n;
            int sum = 0;
            for (int j = 0; j < i; j++) {
                sum += nums[j];
                if (seen.contains(target - sum)) {
                    return true;
                }
                for (int k = j + 1; k < i; k++) {
                    sum += nums[k];
                    if (seen.contains(target - sum)) {
                        return true;
                    }
                    if (k > 0) {
                        sum -= nums[k - 1];
                    }
                }
                if (j > 0) {
                    sum -= nums[j - 1];
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }

    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] dp = new boolean[sum + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int i = sum; i >= num; i--) {
            dp[i] = dp[i] || dp[i - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if ((sum * i) % n == 0 && dp[(sum * i) / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            Set<Integer> subsetSum = new HashSet<>();
            subsetSum.add(0);
            for (int num : nums) {
                Set<Integer> newSubsetSum = new HashSet<>();
                for (int s : subsetSum) {
                    newSubsetSum.add(s + num);
                }
                subsetSum.addAll(newSubsetSum);
                if (subsetSum.contains(sum * i / n)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int i = 1; i < n; i++) {
        if (sum * i % n == 0) {
            return true;
        }
    }

    Set[] sets = new Set[n];
    for (int i = 0; i < n; i++) {
        sets[i] = new HashSet<>();
    }

    sets[0].add(0);

    for (int i = 0; i < n; i++) {
        for (int j = n - i - 1; j > 0; j--) {
            for (int sumSubset : sets[j - 1]) {
                sets[j].add(sumSubset + nums[i]);
            }
        }
    }

    for (int i = 1; i < n; i++) {
        if (sum * i % n == 0) {
            for (int sumSubset : sets[i]) {
                if (sumSubset * n % i == 0 && sumSubset != sum * i / n) {
                    return true;
                }
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length <= 0) {
        throw new IllegalArgumentException("Invalid input: cost array is null or empty");
    }

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Input cost array is null or empty");
    }

    int n = cost.length;
    if (n <= 1) {
        return 0;
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }
    if (cost.length == 2) {
        return Math.min(cost[0], cost[1]);
    }

    for (int i = 2; i < cost.length; i++) {
        cost[i] += Math.min(cost[i - 1], cost[i - 2]);
    }

    return Math.min(cost[cost.length - 1], cost[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

