public int minInsertions(String s) {
    int left = 0;
    int right = 0;
    int result = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            if (right % 2 != 0) {
                result += 1;
                right--;
            }
            left++;
        } else {
            right++;
            if (i == s.length() - 1 || s.charAt(i + 1) != ')') {
                result += 1;
            } else {
                i++;
            }
        }
    }

    return result + left * 2 + right;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
            }
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++;
            } else {
                insertions++;
            }
        }
    }
    return insertions + balance * 2;
}

public int minInsertions(String s) {
    int left = 0, right = 0, result = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right > 0) {
                result += 1;
                right -= 1;
            }
            left += 1;
        } else {
            right += 1;
            if (right == 2) {
                right = 0;
                if (left == 0) {
                    result += 1;
                } else {
                    left -= 1;
                }
            }
        }
    }
    return result + left * 2 + right * 2;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            balance++;
        } else {
            balance--;

            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as it's already processed
            } else {
                insertions++; // Insert a ')' to balance the '('
            }

            if (balance < 0) {
                balance = 0;
                insertions++; // Insert a '(' to balance the ')'
            }
        }
    }

    return insertions + balance * 2; // Each unbalanced '(' needs one ')' and vice versa
}

