public int maxUniqueSplit(String s) {
    Set<String> uniqueSubstrings = new HashSet<>();
    return backtrack(s, 0, uniqueSubstrings);
}

private int backtrack(String s, int start, Set<String> uniqueSubstrings) {
    if (start == s.length()) {
        return uniqueSubstrings.size();
    }
    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (uniqueSubstrings.add(substring)) {
            maxUnique = Math.max(maxUnique, backtrack(s, end, uniqueSubstrings));
            uniqueSubstrings.remove(substring);
        }
    }
    return maxUnique;
}

public int maxUniqueSplit(String s) {
    return maxUniqueSplit(s, 0, new HashSet<>());
}

private int maxUniqueSplit(String s, int start, Set<String> seen) {
    if (start == s.length()) {
        return seen.size();
    }
    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (!seen.contains(substring)) {
            seen.add(substring);
            maxUnique = Math.max(maxUnique, maxUniqueSplit(s, end, seen));
            seen.remove(substring);
        }
    }
    return maxUnique;
}

