public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    if (low > high) {
        return steppingNumbers;
    }

    LinkedList<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num < low) continue;
        if (num > high) break;
        steppingNumbers.add(num);

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            queue.offer(num * 10 + (lastDigit - 1));
        }
        if (lastDigit < 9) {
            queue.offer(num * 10 + (lastDigit + 1));
        }
    }

    return steppingNumbers;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        if (low > high) {
            return steppingNumbers;
        }
        for (int i = 0; i <= 9; i++) {
            if (i >= low) {
                steppingNumbers.add(i);
            }
            LinkedList<Integer> queue = new LinkedList<>();
            queue.add(i);
            while (!queue.isEmpty() && queue.peek() < high) {
                int current = queue.poll();
                int lastDigit = current % 10;
                if (lastDigit != 0) {
                    int prev = current * 10 + lastDigit - 1;
                    if (prev <= high) {
                        queue.add(prev);
                        if (prev >= low) {
                            steppingNumbers.add(prev);
                        }
                    }
                }
                if (lastDigit != 9) {
                    int next = current * 10 + lastDigit + 1;
                    if (next <= high) {
                        queue.add(next);
                        if (next >= low) {
                            steppingNumbers.add(next);
                        }
                    }
                }
            }
        }
        steppingNumbers.sort(Integer::compareTo);
        return steppingNumbers;
    }

