            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) {
                continue;
            }

            int lastDigit = num % 10;
            if (lastDigit > 0) {
                queue.offer(num * 10 + (lastDigit - 1));
