public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low <= 0) {
        result.add(0);
    }
    for (int i = 1; i <= 9; i++) {
        helper(i, low, high, result);
    }
    result.sort(Integer::compareTo);
    return result;
}

private static void helper(int num, int low, int high, List<Integer> result) {
    if (num > high) {
        return;
    }
    if (num >= low) {
        result.add(num);
    }
    int lastDigit = num % 10;
    if (lastDigit > 0) {
        helper(num * 10 + lastDigit - 1, low, high, result);
    }
    if (lastDigit < 9) {
        helper(num * 10 + lastDigit + 1, low, high, result);
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.add(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num == 0 || num > high) {
            continue;
        }
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    long factor = 1;

    while (factor <= n) {
        long lowerNumbers = n - (n / (10 * factor)) * (10 * factor);
        long currentDigit = (n / factor) % 10;
        long higherNumbers = n / (10 * factor);

        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

