    }

    int n = A.length;
    boolean[] visited = new boolean[n];
    int count = 0;

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            count += permute(A, visited, i, 1);
        }
    }

    return count;
}

private static int permute(int[] A, boolean[] visited, int start, int length) {
    if (length == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(A[start] + A[i])) {
            visited[i] = true;
            count += permute(A, visited, i, length + 1);
            visited[i] = false;
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }
    int root = (int) Math.floor(Math.sqrt(num));
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    boolean[] used = new boolean[A.length];
    return backtrack(A, used, 0);
}

private static int backtrack(int[] A, boolean[] used, int start) {
    if (start == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            for (int j = start - 1; j < start; j++) {
                if (j >= 0 && !isPerfectSquare(A[j] + A[i])) {
                    continue;
                }
            }
            used[i] = true;
            count += backtrack(A, used, start + 1);
            used[i] = false;
        }
    }
    return count;
}

private static boolean isPerfectSquare(int n) {
    if (n < 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(n);
    return sqrt * sqrt == n;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    Map<Integer, List<Integer>> adjList = new HashMap<>();
    for (int i = 0; i < A.length; i++) {
        adjList.put(i, new ArrayList<>());
    }

    for (int i = 0; i < A.length; i++) {
        for (int j = i + 1; j < A.length; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                adjList.get(i).add(j);
                adjList.get(j).add(i);
            }
        }
    }

    int count = 0;
    boolean[] visited = new boolean[A.length];
    for (int i = 0; i < A.length; i++) {
        if (!visited[i]) {
            count += countPermutations(i, adjList, visited);
        }
    }

    return count;
}

private static int countPermutations(int start, Map<Integer, List<Integer>> adjList, boolean[] visited) {
    if (visited[start]) {
        return 1;
    }

    visited[start] = true;
    int count = 1;
    for (int neighbor : adjList.get(start)) {
        count += countPermutations(neighbor, adjList, visited);
    }

    visited[start] = false;
    return count;
}

public static int squarePermutations(int[] A) {
    int count = 0;
    int n = A.length;
    boolean[] visited = new boolean[n];

    backtrack(A, visited, 0, count);

    return count;
}

private static void backtrack(int[] A, boolean[] visited, int start, int count) {
    if (start == A.length - 1) {
        count++;
        return;
    }

    for (int i = start + 1; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(A[start] + A[i])) {
            visited[i] = true;
            backtrack(A, visited, start + 1, count);
            visited[i] = false;
        }
    }
}

