            for (int i = Math.min(d, rows - 1); i >= Math.max(0, d - cols + 1); i--) {
                result[k++] = mat[i][d - i];
            }
        } else {
            // Bottom to top
            for (int i = Math.max(0, d - cols + 1); i <= Math.min(d, rows - 1); i++) {
                result[k++] = mat[i][d - i];
            }
