public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) return result;
    centerSymmetricNumbersHelper(n, result, new StringBuilder());
    return result;
}

private static void centerSymmetricNumbersHelper(int n, List<String> result, StringBuilder sb) {
    int len = sb.length();
    if (len == n) {
        if (len == 0 || (len == 1 && sb.charAt(0) != '0')) result.add(sb.toString());
        return;
    }
    for (char sym : new char[]{'0', '1', '6', '8', '9'}) {
        sb.append(sym);
        if (sym == '6') sb.append('9');
        else if (sym == '9') sb.append('6');
        centerSymmetricNumbersHelper(n, result, sb);
        sb.setLength(len);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n < 0) {
        return result;
    }
    char[] numbers = {'0', '1', '6', '8', '9'};
    char[] map = {'0', '1', '9', '8', '6'};
    helper(result, new char[n], numbers, map, 0, n - 1);
    return result;
}

private static void helper(List<String> result, char[] current, char[] numbers, char[] map, int left, int right) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        for (char num : numbers) {
            if (num == '0' && left != 0) continue;
            current[left] = num;
            result.add(new String(current));
        }
        return;
    }
    for (int i = 0; i < 5; i++) {
        current[left] = numbers[i];
        current[right] = map[i];
        helper(result, current, numbers, map, left + 1, right - 1);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        char[] map = {'0', '1', '8', '6', '9'};
        helper(result, new char[n], 0, n - 1, map);
        return result;
    }

private static void helper(List<String> result, char[] current, int left, int right, char[] map) {
        if (left > right) {
            result.add(new String(current));
            return;
        }
        if (left == right) {
            for (char c : map) {
                if (c != '0' || current.length > 1) {
                    current[left] = c;
                    result.add(new String(current));
                }
            }
            return;
        }
        for (char c : map) {
            if (c != '0') {
                current[left] = c;
                current[right] = getSymmetric(c);
                helper(result, current, left + 1, right - 1, map);
            }
        }
    }

private static char getSymmetric(char c) {
        switch (c) {
            case '6':
                return '9';
            case '9':
                return '6';
            default:
                return c;
        }
    }

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        backtrack(result, new StringBuilder(), n, n);
        return result;
    }

private static void backtrack(List<String> result, StringBuilder current, int maxLen, int length) {
        if (length == 0) {
            result.add(current.toString());
            if (maxLen == (current.length() + 2)) {
                result.add("0" + current + "0");
            }
            return;
        }
        if (length == 1) {
            for (char c : new char[]{'0', '1', '8'}) {
                current.append(c);
                result.add(current.toString());
                current.deleteCharAt(current.length() - 1);
            }
            return;
        }
        for (char[] pair : new char[][]{{'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}}) {
            current.append(pair[0]);
            backtrack(result, current, maxLen, length - 2);
            current.deleteCharAt(current.length() - 1);
        }
    }

public static List<String> centerSymmetricNumbers(int n) {
        if (n <= 0) {
            return new ArrayList<>();
        }
        if (n == 1) {
            return new ArrayList<String>() {{
                add("0");
                add("1");
                add("8");
            }};
        }
        List<String> result = helper(n, true);
        if (n % 2 == 0) {
            return result;
        }
        List<String> resultWithoutZero = new ArrayList<>();
        for (String s : result) {
            if (s.charAt(0) != '0') {
                resultWithoutZero.add(s);
            }
        }
        return resultWithoutZero;
    }

private static List<String> helper(int n, boolean allowZero) {
        if (n == 0) {
            return new ArrayList<>(List.of(""));
        }
        if (n == 1) {
            return new ArrayList<>(List.of("0", "1", "8"));
        }
        List<String> prev = helper(n - 2, false);
        List<String> result = new ArrayList<>();
        for (String s : prev) {
            result.add("1" + s + "1");
            result.add("6" + s + "9");
            result.add("8" + s + "8");
            result.add("9" + s + "6");
        }
        if (allowZero) {
            result.add("0" + s + "0");
        }
        return result;
    }

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    if (points[0] == null || points[1] == null || points[2] == null) {
        return false;
